!function(){"use strict";const t=document.getElementById("toggle-theme");function e(){const e="light"===document.firstElementChild.getAttribute("data-theme");t.setAttribute("aria-label",e?"Switch to dark mode":"Switch to light mode")}t.addEventListener("click",(()=>{const t="light"===document.firstElementChild.getAttribute("data-theme")?"dark":"light";document.firstElementChild.setAttribute("data-theme",t),e()})),e()}();